        for(let i=1;i<ROOM_GRID_COLS;i++){ const x=fx(fx0+(fx1-fx0)*i/ROOM_GRID_COLS); const p0=M.px(x,fy(wallsH)), p1=M.px(x,fy(dY1)); gx.beginPath(); gx.moveTo(p0[0],p0[1]); gx.lineTo(p1[0],p1[1]); gx.stroke(); }
