    const vx=b[0]-a[0], vy=b[1]-a[1], L2=vx*vx+vy*vy; if(L2<1e-9)continue;
    const u=((px-a[0])*vx+(py-a[1])*vy)/L2; if(u<0.06||u>0.94)continue;
