      if(!gi.length&&!folderChildren(cur).length){ const ph=document.createElement('div'); ph.className='folderdrop'; ph.dataset.fname=cur; ph.textContent=T('Drag media here','Arrastra medios aquí'); list.appendChild(ph); }
