    {v:'discard',id:'c3Discard',label:(opts.discard||T('Discard','Descartar')),style:'background:#33383F;border-color:rgba(255,255,255,0.2);color:#fff;'},
    {v:'save',id:'c3Save',label:(opts.save||T('Save','Guardar')),primary:true}
