      +'<button id="tourNext" class="togbtn2 on">'+(last?T('Done','Listo'):T('Next','Siguiente'))+'</button></div>';
    card.querySelector('#tourSkip').onclick=end; card.querySelector('#tourNext').onclick=()=>{ if(last)end(); else go(1); };
