    let cx,cy; if(r&&r.width>0){ cx=Math.min(vw-cw-m,Math.max(m,r.left+r.width/2-cw/2)); cy=(r.bottom+m+ch<vh)?(r.bottom+m):Math.max(m,r.top-ch-m); }
