function gridLabel(){ const g=gridSec(),fps=state.fps||30; if(state.tl.tcMode==='frames'||g<1){ const f=Math.max(1,Math.round(g*fps)); return f+' '+(f===1?T('frame','fotograma'):T('frames','fotogramas')); } return (g%1===0?g:g.toFixed(2))+' s'; }
