function gridNarrow(){ state.tl.gridDiv=Math.min(8,(state.tl.gridDiv||0)+1); renderTimeline(); flashGrid(); }
function gridWiden(){ state.tl.gridDiv=Math.max(-8,(state.tl.gridDiv||0)-1); renderTimeline(); flashGrid(); }
