    const cfg={ walls:walls.map(w=>({role:w.role,order:Math.max(1,Math.round(w.order)),wcm:Math.max(1,w.wcm),hcm:Math.max(1,w.hcm),pxW:Math.max(16,Math.round(w.pxW)),pxH:Math.max(16,Math.round(w.pxH))})), fps, floor:null };
